final_check.command:
ruby -rjson -rdigest -e '
base=ARGV.fetch(0)
jsons=Dir.glob(File.join(base,"**","*.json"));jsons.each{|p|JSON.parse(File.read(p))}
result={}
%w[controls03 controls04 picture01 picture02].each do |run|
 r=JSON.parse(File.read(File.join(base,run,"receipt.json")));raise "run not complete" unless r["status"]=="complete"&&r["before"]==r["after"]
 r["before"]["pins"].each{|f,w|raise "method pin changed" unless File.size(f)==w["bytes"]&&Digest::SHA256.file(f).hexdigest==w["sha256"]}
 r["products"].each{|f,w|q=File.join(base,run,f);raise "product pin changed" unless File.size(q)==w["bytes"]&&Digest::SHA256.file(q).hexdigest==w["sha256"]}
 result[run]={products:r["products"].size,bytes:r["products"].values.sum{|x|x["bytes"]},status:r["status"]}
end
v=JSON.parse(File.read(File.join(base,"independent-visual-review.json")))
v.fetch("inputs").fetch("inspected_images").each{|x|raise "visual source changed" unless Digest::SHA256.file(x["path"]).hexdigest==x["sha256"]}
raise "visual count differs" unless v["inputs"]["inspected_images"].size==22
ind=JSON.parse(File.read(File.join(base,"independent-check.json")));raise "independent incomplete" unless ind["status"]=="complete"&&ind["verification"]["pairs"]==228
report=File.join(base,"report.md");links=File.read(report).scan(/\]\(([^)]+)\)/).flatten.reject{|x|x.start_with?("http://","https://","#")}
raise "broken report link" unless links.all?{|x|File.exist?(File.expand_path(x.split("#").first,base))}
names=%w[PROTOCOL.md config.json preparation-review.json picture_screen.py test_picture_screen.py test_picture_screen.pre-sequence.py independent_check.py independent-check.json root-observations.json independent-visual-review.json execution.json report.md]
pins=names.to_h{|n|f=File.join(base,n);[n,{bytes:File.size(f),sha256:Digest::SHA256.file(f).hexdigest}]}
puts JSON.pretty_generate({status:"pass",json_files:jsons.size,run_products:result,visual_source_pins:22,local_report_links:links.size,pins:pins})
' /Users/admin/docs/911-worktrees/sherlock-wtc7-investigation/research/sherlock-wtc7-investigation/audio-listening-2026-10-05/c-source-lineage/picture-correspondence
